insert into public.programs (slug, name, funder, level, province, type, summary, industries, stages, min_amount, max_amount, cost_share_pct, intake_open, intake_close, rolling, official_url, last_verified_at, is_sample, is_featured, featured_order, badge, headline, subheadline, status_text, close_at, calculator, official_contact, disclaimer, content) values
('redip', 'Rural Economic Diversification and Infrastructure Program (REDIP)', 'Province of British Columbia — Rural Programs', 'provincial', 'BC', 'grant', 'Up to $1M for studies, designs and construction of economic infrastructure that creates jobs and new industry in rural B.C.', '{}'::text[], array['idea','preseed','seed','growth','expansion']::text[], null, 1000000, 80, '2026-09-18', '2026-11-21T07:59:00Z', false, 'https://www2.gov.bc.ca/gov/content/employment-business/economic-development/support-organizations-community-partners/rural-economic-development/redip', '2026-10-04', false, true, 1, 'B.C. Provincial · Grant', 'Build in rural B.C. Get up to $1M to do it.', 'The Rural Economic Diversification and Infrastructure Program (REDIP), explained in plain language — plus a quick check to see if your project fits.', 'Intake 5 closes November 20, 2026, 11:59 PM PST', '2026-11-21T07:59:00Z', 'redip', 'RuralDevelopment@gov.bc.ca · 1-250-356-7950', 'Funding Lab is an independent advisor, not part of the Government of B.C. Always confirm with the official program: RuralDevelopment@gov.bc.ca · 1-250-356-7950.', '{"oneMinute":[{"title":"Who runs it","body":"The Province of B.C. (Rural Programs). It''s a grant, not a loan."},{"title":"What it does","body":"Pays for studies, designs and construction of economic infrastructure that create jobs and new industry in rural B.C."},{"title":"What''s new","body":"Projects must align with B.C.''s Look West Economic Strategy or a B.C. Major Project. Tariff-hit communities, such as forestry towns, get priority."}],"keyNumbers":[{"value":"$1M","label":"Maximum grant per project"},{"value":"80%","label":"Of eligible costs under $500K (60% at $500K+)"},{"value":"Nov 20","label":"Intake 5 closes, 11:59 PM PST"},{"value":"Spring 2027","label":"Funding decisions"}],"streams":[{"name":"Development","tag":"Plan it","amount":"Up to $100K · 80% of eligible costs","body":"Feasibility studies, business cases, market analysis, engineering design, and environmental and archaeological assessments, so a project can start within 6 months."},{"name":"Implementation","tag":"Build it","amount":"Up to $1M · 80% under $500K (max $400K), 60% at $500K+ (max $1M)","body":"New or improved economic infrastructure, plus equipment for training or business scale-up. Should be shovel-ready."},{"name":"Community Transition","tag":"Recover","amount":"Case by case · contact the program first","body":"For communities losing a major employer, or with an urgent need tied to a B.C. Major Project."}],"streamsNotes":["One application, one stream per applicant per intake."],"qualifies":[{"heading":"Can lead an application","tone":"yes","items":["Municipalities and regional districts in Rural 1–3 areas","First Nations governments and Indigenous economic development corporations anywhere in B.C.","Not-for-profits with projects in Rural 1–3 areas"]},{"heading":"Can join as a partner (up to 2)","tone":"info","items":["Businesses, including limited partnerships","Industry organizations","Post-secondary institutions","Community foundations and development corporations"]},{"heading":"Can''t lead","tone":"no","items":["For-profit businesses and limited partnerships","Registered charities","Urban 1–3 communities"]}],"partnerPath":{"title":"Partner path for companies","steps":["Your company has a job-creating rural project","A rural lead (municipality, regional district, First Nation or non-profit) agrees to apply","Joint application naming you as partner, with a support letter","REDIP covers up to 80%; you and the lead share the rest"],"conditions":["Broad community benefit","No harm to local competitors","Partner cash and in-kind count toward the lead''s 20–40% share"]},"locationCheck":"Rural 1–3 areas are eligible, Urban 1–3 are not, and Indigenous communities are always eligible. Check your location with the official REDIP Eligibility Lookup Tool on the program page.","sectors":{"title":"Look West priority sectors","chips":["Trade & Logistics","Maritime","AI & Quantum Computing","Aerospace","Life Sciences","Construction Innovation","Agriculture & Food","Tourism","Skilled Workers","Clean Energy","Critical Minerals & Mining","Industrial Land","Defence","A B.C. Major Project in the region"],"note":"Priority goes to tariff-hit sectors such as forestry."},"fits":{"good":["Logistics warehouse or freight-hub servicing","Greenhouse or food processing","Mass-timber or value-added wood equipment","Trades-training equipment","Solar, wind or transmission","Industrial-park sewer, grading or drainage","New tourism features"],"notFunded":["Recreation centres, playgrounds, libraries","Housing or residential servicing","Roads, sidewalks, residential water and sewer","Fire halls and emergency vehicles","Mental health or wellness facilities","Community plans, OCPs, strategic plans","Routine repairs"],"rule":"Rule of thumb: if it doesn''t clearly drive jobs, business or industry, it won''t qualify."},"calculatorNotes":["In-kind contributions (staff time, space, equipment) can count for up to 10% of the budget at fair market value.","Other B.C. provincial funding doesn''t count toward your share.","Cost overruns are yours.","Applications short of the minimum contribution are not assessed."],"eligibleCosts":[{"cost":"Consultants, engineering, design, project management","covered":true},{"cost":"Construction, materials, utility hookups","covered":true},{"cost":"Equipment and capital","covered":true,"note":"Max 50% of the grant"},{"cost":"Staff wages for project work","covered":true,"note":"Max 25% of the grant"},{"cost":"Indigenous consultation, marketing, travel at government rates","covered":true},{"cost":"Land purchase","covered":false},{"cost":"GST/PST, financing, interest","covered":false},{"cost":"Legal fees, permits, approvals","covered":false},{"cost":"Anything spent before approval","covered":false,"note":"Don''t start early"}],"howToWin":[{"title":"Link to Look West","body":"Show how the project grows a Look West priority sector or supports a B.C. Major Project."},{"title":"Jobs soon","body":"Count the jobs created or retained, and show when they start."},{"title":"Shovel-ready","body":"Permits, designs and site control in hand, or a clear path to them."},{"title":"Tariff impact","body":"Explain how the project helps a community hit by U.S. tariffs."},{"title":"Committed partners","body":"Signed partner letters, not intentions."},{"title":"Real quotes","body":"Quotes for every major cost, matched line by line to the budget template."}],"howToWinNote":"REDIP has historically been heavily oversubscribed.","keyDates":[{"date":"Sep 18, 2026","label":"Intake 5 opened"},{"date":"Now","label":"Register Business BCeID and book a pre-application meeting"},{"date":"Nov 20, 2026","label":"Intake closes, 11:59 PM PST","body":"Applying early gives no advantage."},{"date":"Dec 31, 2026","label":"Late council resolutions due","body":"If delayed by the Oct 17 local elections. Past REDIP reports must be done."},{"date":"Spring 2027","label":"Funding decisions"},{"date":"After award","label":"Start within 1 year, finish within 2 years"}],"keyDatesCallout":"Business BCeID can take several weeks. Meet REDIP staff or your Regional Manager before applying.","docChecklist":[{"group":"Everyone","items":["REDIP budget template (Excel)","Quotes for all major costs","Letter from each partner","Direct deposit form and void cheque","Business BCeID"]},{"group":"Building projects","items":["Permits, assessments and approvals","KML site map","Drawings and engineering","Gantt chart or timeline","Letters confirming other funding"]},{"group":"Nice to have","items":["Business case (ROI, risks, cost-benefit)","3-year revenue projections","Timeline for planning projects","Council or board resolution"]}],"quickCheck":{"intro":"Tick every statement that''s true for your project.","items":[{"id":"location","label":"The project is in a Rural 1–3 area or an Indigenous community"},{"id":"lead","label":"An eligible lead will apply (or you are one)"},{"id":"sector","label":"It grows a Look West sector and creates jobs"},{"id":"share","label":"You can cover 20% (under $500K) or 40% ($500K+) of costs"},{"id":"timing","label":"Nothing is spent before approval, and work starts within a year"},{"id":"type","label":"It is not recreation, housing, roads or emergency services"}],"bands":[{"min":6,"max":6,"tone":"strong","title":"Strong fit. Let''s build your application.","body":"Book a fit call and we''ll map your lead, partners and budget."},{"min":4,"max":5,"tone":"fixable","title":"Fixable gaps. We''ll help close them before Nov 20.","body":"Most gaps are about the lead applicant or cost share. Both are solvable."},{"min":0,"max":3,"tone":"weak","title":"Probably not REDIP this round.","body":"We''ll point you to a better-fit program."}]},"nextSteps":["Send us your quick-check answers","30-minute fit call","Secure your lead applicant and partner letters","Build the application","Submit by Nov 20, and report if funded"],"officialLinks":[{"label":"Official REDIP program page","url":"https://www2.gov.bc.ca/gov/content/employment-business/economic-development/support-organizations-community-partners/rural-economic-development/redip"}]}'::jsonb),
('rtri', 'Regional Tariff Response Initiative (RTRI) — British Columbia', 'Pacific Economic Development Canada (PacifiCan)', 'federal', 'BC', 'contribution', 'Non-repayable liquidity and pivot funding, plus interest-free repayable loans, for B.C. businesses hit by U.S. tariffs.', '{}'::text[], array['growth','expansion','exit']::text[], null, 20000000, 50, '2025-03-21', null, true, 'https://www.canada.ca/en/pacific-economic-development/services/funding/regional-tariff-response-initiative.html', '2026-10-04', false, true, 2, 'Federal · PacifiCan · Non-repayable + interest-free repayable', 'Hit by U.S. tariffs? Get up to $3M you don''t repay.', 'The Regional Tariff Response Initiative (RTRI) in British Columbia, explained in plain language: the money, the rules, the numbers and how to apply.', 'Open now · first come, first served · funding is finite', null, 'rtri', 'PacifiCan · 1-888-338-9378', 'Funding Lab is an independent advisor, not part of the Government of Canada or PacifiCan. Always confirm with PacifiCan: 1-888-338-9378.', '{"heroStats":[{"value":"$3M","label":"Non-repayable per business"},{"value":"$20M","label":"Total ceiling incl. repayable"},{"value":"$3.45B","label":"National RTRI fund"},{"value":"Open","label":"First come, first served"}],"whyItMatters":{"intro":"52.8% of B.C. goods exports went to the U.S. in 2024: $28.7B shipped. The top exports:","bars":[{"label":"Softwood lumber","value":3.3,"display":"$3.3B"},{"label":"Natural gas","value":2.4,"display":"$2.4B"},{"label":"Machinery & equipment","value":2.3,"display":"$2.3B"},{"label":"Petroleum & fuels","value":2.1,"display":"$2.1B"},{"label":"Agriculture & food","value":1.9,"display":"$1.9B"}],"note":"Source: BC Stats, 2024 data.","facts":["Federal $7.5B package (Aug 25, 2026) adds $1.5B to RTRI; the national fund is $3.45B over 4 years.","B.C. expansion announced Sep 8, 2026 adds liquidity support up to $2M.","PacifiCan since 2021: $708M invested in 783 projects across 177 communities."]},"oneMinute":[{"title":"Who runs it","body":"Pacific Economic Development Canada (PacifiCan)."},{"title":"What it does","body":"Keeps your team paid through the crunch and funds projects that make you more competitive and less reliant on one market."},{"title":"What''s new","body":"Expanded in September 2026 with liquidity support of up to $2M."}],"keyNumbers":[{"value":"$3M","label":"Max non-repayable ($2M liquidity + $1M pivot)"},{"value":"$20M","label":"Max total incl. interest-free repayable"},{"value":"$1M+","label":"Annual revenue in one of the last two fiscal years"},{"value":"~90 days","label":"Decision target (business days); claims paid in ~15"}],"streams":[{"name":"Liquidity support","tag":"Stay afloat","amount":"Up to $2M non-repayable","body":"50% of payroll for up to 12 months. Covers wages plus essential costs (rent, utilities, insurance, property taxes). Liquidity periods end by Mar 31, 2028."},{"name":"Pivot project","tag":"Adapt","amount":"Up to $1M non-repayable","body":"Up to 50% of project costs: productivity, equipment and technology, new markets, supply chains. One non-repayable project per business."},{"name":"Large pivot project","tag":"Transform","amount":"Over $1M · interest-free repayable","body":"Up to 75% of costs. No collateral, no early-repayment penalty. Finish by Mar 31, 2029."}],"streamsNotes":["Not-for-profits supporting tariff-hit businesses have a separate stream (no liquidity support).","Non-repayable project funding is available once per business; a single project is either repayable or non-repayable.","Other government programs are OK, but not for the same costs."],"qualifies":[{"heading":"Business","tone":"yes","items":["Incorporated, for-profit, located and operating in B.C."]},{"heading":"Revenue","tone":"yes","items":["$1M+ annual revenue in one of the last two fiscal years"]},{"heading":"Viability","tone":"yes","items":["Viable before tariffs"]},{"heading":"Tariff impact (any one)","tone":"yes","items":["In a tariffed sector (Section 232 or other U.S. tariffs), as exporter or supplier","25%+ of revenue from goods ultimately exported to the U.S.","Real damage: big cost increases, supply disruption, lost customers or revenue"]},{"heading":"Not eligible","tone":"no","items":["No direct or indirect tariff exposure","Businesses started after Mar 21, 2025 are considered case by case"]}],"pivotExamples":["Boost productivity","Adopt proven technology (not early-stage R&D)","Find new markets: Canada, Europe, Asia","Fix supply chains","Reshore work to B.C.","Show measurable results with local and regional benefits"],"calculatorNotes":["Other aid for the same costs reduces liquidity support.","You commit to keep operating and keep staff in Canada.","Pivot projects need at least 10% from non-government sources.","Repayable: 0% interest, 12-month grace after project end, then 60 monthly payments. Late payments bear bank rate + 3%. Final terms are set in your agreement."],"proof":{"counts":["Bank statements","Unused lines of credit","Signed funding letters"],"doesntCount":["Forecast revenue","Receivables","Promised equity","SR&ED not yet received"]},"eligibleCosts":[{"cost":"Wages, rent, utilities, insurance, property taxes","covered":true,"note":"Liquidity"},{"cost":"Project labour and materials","covered":true,"note":"New, added costs only"},{"cost":"Machinery, equipment, infrastructure","covered":true},{"cost":"Consultants and professional services","covered":true},{"cost":"Costs to expand or keep markets","covered":true},{"cost":"Land and buildings","covered":false},{"cost":"Early-stage R&D (TRL 1–6)","covered":false},{"cost":"Bonuses, dividends, debt refinancing","covered":false},{"cost":"Income taxes, GST, vehicles, entertainment","covered":false},{"cost":"Tariffs and duties, raw materials, inventory","covered":false}],"howToWin":[{"title":"Hard tariff evidence","body":"Customs records, supplier notices, export sales data."},{"title":"Viable before tariffs","body":"Show the business worked before the shock."},{"title":"Realistic, on-time plan","body":"Milestones you can actually hit."},{"title":"Matching funds above the minimum","body":"More of your own money gets priority."},{"title":"Canadian roots","body":"50%+ Canadian-owned, Canadian inputs."},{"title":"Clear B.C. benefits","body":"Jobs, revenue, exports."}],"howToWinNote":"Applications are processed in the order received.","keyDates":[{"date":"Mar 21, 2025","label":"Earliest date project costs can count","body":"Costs can go back up to 12 months before your signed application, never before this date."},{"date":"Aug 22, 2026","label":"Liquidity eligibility period opens"},{"date":"Now","label":"Apply online — processed in order received"},{"date":"~90 business days","label":"Decision target"},{"date":"Mar 31, 2028","label":"Liquidity periods end"},{"date":"Mar 31, 2029","label":"Pivot projects complete"}],"keyDatesCallout":"Keep every invoice.","docChecklist":[{"group":"Everyone","items":["2 years of financial statements (external accountant) plus interim","Incorporation documents and CRA business number","Tariff evidence (customs records, supplier notices, export sales data)","List of other government funding","Signed attestation form"]},{"group":"Liquidity","items":["Last 12 months of payroll and CRA remittances","12-month income and cash-flow forecast","Proof of cash need","12 months of rent, utilities, insurance, property tax (if claimed)","Job retention targets"]},{"group":"Pivot","items":["Project plan with milestones and budget","Business plan (tariff impact, edge, team)","Forecasts for the project + 2 years","Proof of your share","Quotes and support letters"]}],"docNote":"Apply through PacifiCan''s online portal (stream: BC (PacifiCan) - RTRI-Business). Missing documents mean an incomplete application.","quickCheck":{"intro":"Tick every statement that''s true for your business.","items":[{"id":"incorporated","label":"Incorporated for-profit business located and operating in B.C."},{"id":"revenue","label":"$1M+ revenue in one of the last two fiscal years"},{"id":"viable","label":"Viable before tariffs"},{"id":"impact","label":"Can show tariff impact: tariffed sector, 25%+ of revenue from U.S. exports, or real damage"}],"bands":[{"min":4,"max":4,"tone":"strong","title":"Strong fit — let''s size your liquidity and pivot funding.","body":"Book a fit call and bring your payroll and export numbers."},{"min":3,"max":3,"tone":"fixable","title":"Possible fit — let''s review your tariff evidence.","body":"Most gaps here are about documentation."},{"min":0,"max":2,"tone":"weak","title":"RTRI may not fit.","body":"We''ll point you to a better program."}]},"nextSteps":["Book a free RTRI fit call","30-minute fit call","Pick your mix: liquidity, pivot, or both","Build the file: forecasts, business plan, tariff evidence, attestation","Submit on PacifiCan''s portal, then keep up with claims and job reporting"],"nextStepsCallout":"A complete file sent early beats a perfect one sent late.","officialLinks":[{"label":"PacifiCan RTRI program page","url":"https://www.canada.ca/en/pacific-economic-development/services/funding/regional-tariff-response-initiative.html"}]}'::jsonb),
